102 | /**
103 |  * Classe principal do serviço Google Drive.
104 |  * Gerencia token OAuth, requisições à API e streaming.
105 |  */
106 | export class GoogleDriveService {
107 |   private accessToken: string | null = null;
108 |   private tokenClient: any = null;
109 |   private gisLoaded: boolean = false;
110 | 
111 |   constructor() {
112 |     this.loadGisApi();
113 |   }
114 | 
115 |   /**
116 |    * Carrega a API Google Identity Services dinamicamente.
117 |    */
118 |   private loadGisApi(): void {
119 |     if (typeof google !== "undefined" && google.accounts) {
120 |       this.gisLoaded = true;
121 |       return;
122 |     }
123 | 
124 |     const script = document.createElement("script");
125 |     script.src = "https://accounts.google.com/gsi/client";
126 |     script.async = true;
127 |     script.defer = true;
128 |     script.onload = () => {
129 |       this.gisLoaded = true;
130 |       console.log("[Llama Player] GIS API carregada");
131 |     };
132 |     script.onerror = () => {
133 |       console.error("[Llama Player] Erro ao carregar GIS API");
134 |     };
135 |     document.head.appendChild(script);
136 |   }
137 | 
138 |   /**
139 |    * Carrega a API Discovery do Google Drive.
140 |    */
141 |   private async loadDriveApi(): Promise<void> {
142 |     return new Promise((resolve, reject) => {
143 |       if (typeof gapi !== "undefined" && gapi.client) {
144 |         resolve();
145 |         return;
146 |       }
147 | 
148 |       const script = document.createElement("script");
149 |       script.src = "https://apis.google.com/js/api.js";
150 |       script.async = true;
151 |       script.defer = true;
152 |       script.onload = () => {
153 |         (gapi as any).load("client", async () => {
154 |           try {
155 |             await (gapi as any).client.init({});
156 |             await (gapi as any).client.load(DISCOVERY_DOC);
157 |             resolve();
158 |           } catch (err) {
159 |             reject(err);
160 |           }
161 |         });
162 |       };
163 |       script.onerror = () => reject(new Error("Erro ao carregar Google API"));
164 |       document.head.appendChild(script);
165 |     });
166 |   }
167 | 
168 |   /**
169 |    * Inicializa o TokenClient com o Client ID.
170 |    * Deve ser chamado após o usuário interagir (clicar em "Login").
171 |    */
172 |   async initialize(clientId: string): Promise<void> {
173 |     // Aguarda GIS carregar
174 |     while (!this.gisLoaded) {
175 |       await new Promise((r) => setTimeout(r, 100));
176 |     }
177 | 
178 |     this.tokenClient = (google as any).accounts.oauth2.initTokenClient({
179 |       client_id: clientId,
180 |       scope: SCOPES,
181 |       callback: (response: any) => {
182 |         if (response.access_token) {
183 |           this.accessToken = response.access_token;
184 |           this.storeToken(response.access_token);
185 |         }
186 |       },
187 |     });
188 | 
189 |     // Carrega Drive API
190 |     await this.loadDriveApi();
191 |   }
192 | 
193 |   /**
194 |    * Dispara o fluxo de login OAuth.
195 |    * Retorna true se autenticou com sucesso.
196 |    */
197 |   async login(): Promise<boolean> {
198 |     if (!this.tokenClient) {
199 |       throw new Error(
200 |         "TokenClient não inicializado. Chame initialize(clientId) primeiro."
201 |       );
202 |     }
203 | 
204 |     return new Promise((resolve) => {
205 |       this.tokenClient!.callback = (response: any) => {
206 |         if (response.access_token) {
207 |           this.accessToken = response.access_token;
208 |           this.storeToken(response.access_token);
209 |           resolve(true);
210 |         } else {
211 |           console.error("[Llama Player] Erro no OAuth:", response.error);
212 |           resolve(false);
213 |         }
214 |       };
215 | 
216 |       // Solicita token (pode abrir popup)
217 |       this.tokenClient!.requestAccessToken({ prompt: "consent" });
218 |     });
219 |   }
220 | 
221 |   /**
222 |    * Tenta fazer login silencioso com token existente.
223 |    */
224 |   async trySilentLogin(clientId: string): Promise<boolean> {
225 |     const storedToken = this.getStoredToken();
226 |     if (!storedToken) return false;
227 | 
228 |     this.accessToken = storedToken;
229 | 
230 |     try {
231 |       await this.initialize(clientId);
232 |       // Verifica se o token ainda é válido
233 |       const user = await this.getUserInfo();
234 |       return !!user;
235 |     } catch {
236 |       this.accessToken = null;
237 |       this.clearToken();
238 |       return false;
239 |     }
240 |   }
241 | 
242 |   /**
243 |    * Faz logout: limpa token e revoga.
244 |    */
245 |   async logout(): Promise<void> {
246 |     if (this.accessToken) {
247 |       try {
248 |         (google as any).accounts.oauth2.revoke(this.accessToken, () => {});
249 |       } catch {
250 |         // Ignora erro no revoke
251 |       }
252 |     }
253 |     this.accessToken = null;
254 |     this.clearToken();
255 |   }
256 | 
257 |   /**
258 |    * Retorna informações do usuário autenticado.
259 |    */
260 |   async getUserInfo(): Promise<DriveUser | null> {
261 |     if (!this.accessToken) return null;
262 | 
263 |     try {
264 |       const response = await fetch(
265 |         "https://www.googleapis.com/oauth2/v2/userinfo",
266 |         {
267 |           headers: { Authorization: `Bearer ${this.accessToken}` },
268 |         }
269 |       );
270 |       if (!response.ok) return null;
271 |       const data = await response.json();
272 |       return {
273 |         email: data.email,
274 |         name: data.name,
275 |         picture: data.picture,
276 |       };
277 |     } catch {
278 |       return null;
279 |     }
280 |   }
281 | 
282 |   /**
283 |    * Lista arquivos e pastas em uma pasta do Drive.
284 |    * Se folderId for null, lista a raiz.
285 |    */
286 |   async listFiles(folderId: string | null = null): Promise<DriveItem[]> {
287 |     if (!this.accessToken) throw new Error("Não autenticado");
288 | 
289 |     const query = folderId
290 |       ? `'${folderId}' in parents and trashed = false`
291 |       : "trashed = false and 'root' in parents";
292 | 
293 |     const fields =
294 |       "files(id,name,mimeType,size,modifiedTime,parents,iconLink,webContentLink)";
295 | 
296 |     try {
297 |       const response = await (gapi as any).client.drive.files.list({
298 |         q: query,
299 |         fields,
300 |         orderBy: "folder,name",
301 |         pageSize: 100,
302 |         includeItemsFromAllDrives: false,
303 |         supportsAllDrives: false,
304 |       });
305 | 
306 |       const files = response.result.files || [];
307 |       return files.map((file: any) => ({
308 |         id: file.id,
309 |         name: file.name,
310 |         mimeType: file.mimeType,
311 |         size: file.size ? parseInt(file.size, 10) : undefined,
312 |         modifiedTime: file.modifiedTime,
313 |         parents: file.parents,
314 |         iconLink: file.iconLink,
315 |         webContentLink: file.webContentLink,
316 |       }));
317 |     } catch (err: any) {
318 |       console.error("[Llama Player] Erro ao listar arquivos:", err);
319 |       throw new Error(
320 |         err?.result?.error?.message || "Erro ao listar arquivos do Drive"
321 |       );
322 |     }
323 |   }
324 | 
325 |   /**
326 |    * Busca arquivos de áudio no Drive por nome.
327 |    */
328 |   async searchAudio(query: string): Promise<DriveFile[]> {
329 |     if (!this.accessToken) throw new Error("Não autenticado");
330 | 
331 |     const mimeFilter = Array.from(AUDIO_MIME_TYPES)
332 |       .map((m) => `mimeType = '${m}'`)
333 |       .join(" or ");
334 | 
335 |     const q = `(name contains '${query.replace(/'/g, "\\'")}') and (${mimeFilter}) and trashed = false`;
336 | 
337 |     try {
338 |       const response = await (gapi as any).client.drive.files.list({
339 |         q,
340 |         fields:
341 |           "files(id,name,mimeType,size,modifiedTime,parents,iconLink,webContentLink)",
342 |         orderBy: "name",
343 |         pageSize: 50,
344 |       });
345 | 
346 |       return (response.result.files || []).map((file: any) => ({
347 |         id: file.id,
348 |         name: file.name,
349 |         mimeType: file.mimeType,
350 |         size: file.size ? parseInt(file.size, 10) : undefined,
351 |         modifiedTime: file.modifiedTime,
352 |         parents: file.parents,
353 |         iconLink: file.iconLink,
354 |         webContentLink: file.webContentLink,
355 |       }));
356 |     } catch (err: any) {
357 |       console.error("[Llama Player] Erro na busca:", err);
358 |       throw new Error(
359 |         err?.result?.error?.message || "Erro ao buscar no Drive"
360 |       );
361 |     }
362 |   }
363 | 
364 |   /**
365 |    * Obtém URL de download direto para um arquivo do Drive.
366 |    * Usa exportLinks para arquivos do Google Docs ou download para binários.
367 |    */
368 |   async getDownloadUrl(fileId: string, _mimeType: string): Promise<string> {
369 |     if (!this.accessToken) throw new Error("Não autenticado");
370 | 
371 |     // Para arquivos de áudio, usa o download direto
372 |     return `https://www.googleapis.com/drive/v3/files/${fileId}?alt=media`;
373 |   }
374 | 
375 |   /**
376 |    * Cria um URL de streaming com o token de acesso.
377 |    * O token expira em 1 hora, então precisa renovar para músicas longas.
378 |    */
379 |   getStreamUrl(fileId: string): string {
380 |     if (!this.accessToken) throw new Error("Não autenticado");
381 |     return `https://www.googleapis.com/drive/v3/files/${fileId}?alt=media&access_token=${this.accessToken}`;
382 |   }
383 | 
384 |   /**
385 |    * Verifica se o token atual é válido fazendo uma requisição leve.
386 |    */
387 |   async validateToken(): Promise<boolean> {
388 |     if (!this.accessToken) return false;
389 |     try {
390 |       const response = await fetch(
391 |         "https://www.googleapis.com/drive/v3/about?fields=user",
392 |         { headers: { Authorization: `Bearer ${this.accessToken}` } }
393 |       );
394 |       return response.ok;
395 |     } catch {
396 |       return false;
397 |     }
398 |   }
399 | 
400 |   // --- Gerenciamento de Token (localStorage) ---
401 | 
402 |   private TOKEN_KEY = "llama-player-drive-token";
403 | 
404 |   private storeToken(token: string): void {
405 |     try {
406 |       localStorage.setItem(this.TOKEN_KEY, token);
407 |     } catch {
408 |       // localStorage pode não estar disponível
409 |     }
410 |   }
411 | 
412 |   private getStoredToken(): string | null {
413 |     try {
414 |       return localStorage.getItem(this.TOKEN_KEY);
415 |     } catch {
416 |       return null;
417 |     }
418 |   }
419 | 
420 |   private clearToken(): void {
421 |     try {
422 |       localStorage.removeItem(this.TOKEN_KEY);
423 |     } catch {
424 |       // Ignora
425 |     }
426 |   }
427 | 
428 |   /**
429 |    * Verifica se o usuário está autenticado.
430 |    */
431 |   isAuthenticated(): boolean {
432 |     return this.accessToken !== null;
433 |   }
434 | 
435 |   /**
436 |    * Retorna o token de acesso atual.
437 |    */
438 |   getAccessToken(): string | null {
439 |     return this.accessToken;
440 |   }
441 | }
442 | 
443 | // Instância singleton do serviço
444 | export const driveService = new GoogleDriveService();
